/**
 * People shown on the issue participants strip: the author, the current
 * assignee, and authors of comments that have not been deleted. Removed
 * members are left out. Order is unspecified.
 */
export async function getIssueParticipants(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly UserId[]> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "comment:read", issueResource(issue));

  const commentAuthorIds = await commentRepo.listCommentAuthorIds(orgId, issueId);
  const candidates = new Set<UserId>([issue.authorId, ...commentAuthorIds]);
  if (issue.assigneeId !== null) candidates.add(issue.assigneeId);

  const participants: UserId[] = [];
  for (const userId of candidates) {
    const member = await memberRepo.findMember(orgId, userId);
    if (member !== null && member.status === "active") {
      participants.push(userId);
    }
  }
  return participants;
}

